<template><main class="workflow" v-loading="loading"><header><div><small>门店人员 / 审批与执行</small><h1>审批流程</h1><p>审批通过后自动调整，或交给人事执行。每份申请保留提交时的流程版本。</p></div><el-button @click="load">刷新</el-button></header><div class="toolbar"><el-radio-group v-model="business"><el-radio-button value="staff-mini-role">小程序岗位调整</el-radio-button><el-radio-button value="staff-reserve-transfer">储备人员调动</el-radio-button><el-radio-button value="staff-manager-appointment">正式店长任命</el-radio-button><el-radio-button value="store-report">门店问题申报</el-radio-button></el-radio-group><el-button v-if="canHQ&&business!=='store-report'&&business!=='staff-mini-role'" type="primary" @click="openAppointment">总部发起申请</el-button></div><StoreReports v-if="business==='store-report'"/><template v-else><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-tabs v-model="tab"><el-tab-pane label="业务记录" name="records"><el-input v-model="search" clearable placeholder="搜索员工、门店或岗位" class="search"/><el-table :data="filtered"><el-table-column prop="employee_name" label="员工" width="120"/><el-table-column prop="store_name" label="门店" min-width="180"/><el-table-column label="岗位／职责" min-width="210"><template #default="{row}">{{row.old_position}} → {{row.new_position}}</template></el-table-column><el-table-column label="进度" min-width="180"><template #default="{row}">{{status(row)}}<p>{{row.flow_name}}</p></template></el-table-column><el-table-column v-if="business!=='staff-mini-role'" prop="to_store_name" label="目标门店" min-width="170"/><el-table-column v-if="business!=='staff-mini-role'" prop="effective_date" label="生效日期" width="120"/><el-table-column label="申请时间" min-width="170"><template #default="{row}">{{time(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="230"><template #default="{row}"><el-button link type="primary" @click="detail=row">明细</el-button><el-button v-if="row.can_review" link type="primary" @click="act(row,'approve')">同意</el-button><el-button v-if="row.can_review" link type="danger" @click="act(row,'reject')">驳回</el-button><el-button v-if="row.can_execute" link type="primary" @click="act(row,'execute')">执行生效</el-button><el-button v-if="row.can_void||row.can_execute" link type="danger" @click="act(row,'void')">作废</el-button></template></el-table-column></el-table><el-empty v-if="!filtered.length" description="暂无岗位调整申请"/></el-tab-pane><el-tab-pane v-if="canManage" label="流程设置" name="templates"><div class="toolbar"><p>同一业务、同一门店仅能匹配一个启用流程。储备人员调动需接收店签收；正式任命不自动变更薪资。</p><el-button type="primary" @click="edit()">新增流程</el-button></div><el-table :data="config.templates"><el-table-column prop="name" label="流程名称"/><el-table-column label="适用范围"><template #default="{row}">{{scopeName(row)}}</template></el-table-column><el-table-column label="审批顺序" min-width="240"><template #default="{row}">{{row.nodes.map(n=>n.name).join(' → ')}}</template></el-table-column><el-table-column label="审批后处理"><template #default="{row}">{{row.execution==='auto'?'自动调岗':'人事确认执行'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{row.enabled?'启用':'停用'}} · v{{row.revision}}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="edit(row)">配置</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs>
<el-dialog v-model="editing" title="审批流程配置" width="760px"><el-form label-position="top"><el-form-item label="流程名称"><el-input v-model="form.name" maxlength="80"/></el-form-item><el-form-item label="适用门店"><el-radio-group v-model="form.mode"><el-radio-button value="all">全部门店</el-radio-button><el-radio-button value="regions">指定区域</el-radio-button><el-radio-button value="stores">指定门店</el-radio-button></el-radio-group><StoreRegionSelect v-if="form.mode==='stores'" v-model="form.store_ids" :stores="config.stores" multiple input-width="100%"/><el-select v-if="form.mode==='regions'" v-model="form.region_ids" multiple filterable><el-option v-for="r in config.regions" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item><div v-for="(n,i) in form.nodes" :key="i" class="node"><div class="node-head"><b>{{i+1}} · 审批节点</b><el-button link type="danger" :disabled="form.nodes.length===1" @click="form.nodes.splice(i,1)">移除</el-button></div><el-input v-model="n.name" placeholder="例如：负责门店的督导审批"/><div class="node-controls"><el-select v-model="n.kind" @change="n.ids=[]"><el-option label="按负责门店的岗位匹配" value="positions"/><el-option label="指定审批人员" value="users"/></el-select><el-select v-model="n.mode"><el-option label="任一人同意" value="any"/><el-option label="所有人同意" value="all"/></el-select></div><el-select v-model="n.ids" multiple filterable placeholder="选择审批岗位或人员"><el-option v-for="p in n.kind==='users'?config.users:config.positions" :key="p.id" :value="p.id" :label="p.name"/></el-select><p>按该岗位的负责门店匹配；排除申请人和被调整员工。没有审批人时阻止提交。</p></div><el-button @click="form.nodes.push(node())" :disabled="form.nodes.length>=8">＋ 添加审批节点</el-button><el-form-item label="没有匹配审批人时（选填）"><el-select v-model="form.fallback_user_ids" multiple filterable placeholder="指定兜底人员；未设置时阻止提交"><el-option v-for="u in config.users" :key="u.id" :value="u.id" :label="u.name"/></el-select></el-form-item><el-form-item label="全部审批通过后" class="execution"><el-radio-group v-model="form.execution"><el-radio value="auto">按生效日期自动执行</el-radio><el-radio value="manual">人事确认后执行</el-radio></el-radio-group></el-form-item><el-switch v-model="form.enabled" active-text="启用流程"/></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存流程</el-button></template></el-dialog>
<el-drawer :model-value="!!detail" @close="detail=null" title="岗位调整明细" size="520px"><template v-if="detail"><h2>{{detail.employee_name}}</h2><p>{{detail.store_name}}</p><p v-if="detail.to_store_name">目标门店：{{detail.to_store_name}} · 生效日期：{{detail.effective_date}}</p><h3>{{detail.old_position}} → {{detail.new_position}}</h3><p>{{detail.reason}}</p><el-alert :title="status(detail)" :closable="false"/><div v-for="(n,i) in detail.nodes" :key="i" class="node"><b>{{i+1}}. {{n.name}}</b><p>{{n.people.map(p=>p.name).join('、')}} · {{n.mode==='all'?'所有人同意':'任一人同意'}}</p></div><el-timeline><el-timeline-item v-for="(e,i) in detail.events" :key="i" :timestamp="time(e.time)">{{e.name}} · {{actions[e.action]}}<p>{{e.note}}</p></el-timeline-item></el-timeline></template></el-drawer><el-dialog v-model="appointmentOpen" title="总部人事申请" width="620px"><el-form label-position="top"><el-form-item label="储备人员"><el-select v-model="appointment.employee_id" filterable><el-option v-for="e in hqOptions.employees" :key="e.id" :value="e.id" :label="e.name+' · '+e.position+' · '+e.store_name"/></el-select></el-form-item><el-form-item label="任职／接收门店"><StoreRegionSelect v-model="appointment.to_store_id" :stores="hqOptions.stores" input-width="100%"/></el-form-item><el-form-item v-if="business==='staff-manager-appointment'" label="正式店长岗位"><el-select v-model="appointment.position_id" filterable><el-option v-for="p in hqOptions.positions.filter(p=>p.store_ids===null||p.store_ids.includes(appointment.to_store_id))" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="appointment.effective_date" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="原因"><el-input v-model="appointment.reason" type="textarea" maxlength="1000" :rows="3"/></el-form-item><el-alert title="保留账号和历史数据。任命生效会交接目标店原店长职责，薪资由人事另行确认。" :closable="false"/></el-form><template #footer><el-button @click="appointmentOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitAppointment">提交审批</el-button></template></el-dialog></template></main></template>
<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {ElMessageBox,ElMessage} from 'element-plus'
import {workflowApi as api} from '@/api'
import {useAuthStore} from '@/stores/auth'
import StoreRegionSelect from '@/components/StoreRegionSelect.vue'
import StoreReports from '@/components/StoreReports.vue'
const auth=useAuthStore(),canManage=computed(()=>(auth.user?.position_permissions||[]).some(p=>p==='*'||p==='workflow.manage'))
const props=defineProps({initialBusiness:{type:String,default:'staff-mini-role'}})
const business=ref(props.initialBusiness),canHQ=computed(()=>(auth.user?.position_permissions||[]).some(p=>p==='*'||p==='staff.hq.manage')),hqOptions=ref({employees:[],stores:[],positions:[]}),appointmentOpen=ref(false),appointment=ref({})
const config=ref({templates:[],stores:[],regions:[],positions:[],users:[]}),rows=ref([]),loading=ref(false),busy=ref(false),error=ref(''),tab=ref('records'),search=ref(''),editing=ref(false),form=ref({nodes:[]}),detail=ref(null)
const actions={blocked:'执行受阻',dispatch:'总部下发',receive:'接收店签收',rejected:'接收店拒绝',cancelled:'调动撤回',submit:'提交申请',approve:'同意',reject:'驳回',cancel:'撤回',execute:'执行生效',void:'作废'},time=v=>new Date(v).toLocaleString('zh-CN',{hour12:false}),node=()=>({name:'督导审批',kind:'positions',ids:[],mode:'any'})
const status=r=>r.execution_error?'执行受阻 · 待总部处理':r.execution_status==='receiving'?'待接收门店签收':r.status==='approved'&&r.execution_status==='waiting'&&r.effective_date>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'})?'待生效 · '+r.effective_date:r.status==='pending'?'待'+r.stage_name:r.status==='approved'?(r.execution_status==='done'?(r.business==='staff-manager-appointment'?'任命已生效':'已完成'):'已通过 · 待人事执行'):r.status==='rejected'?'已驳回':'已撤回／作废'
const filtered=computed(()=>rows.value.filter(r=>[r.employee_name,r.store_name,r.new_position].join(' ').includes(search.value)))
const scopeName=r=>r.mode==='all'?'全部门店':r.mode==='stores'?r.store_ids.map(id=>config.value.stores.find(p=>p.id===id)?.store_name).join('、'):r.region_ids.map(id=>config.value.regions.find(p=>p.id===id)?.name).join('、')
async function load(){if(business.value==='store-report'){loading.value=false;return}loading.value=true;error.value='';try{rows.value=(await api.requests(business.value)).rows;if(canManage.value)config.value=await api.config(business.value);if(canHQ.value&&business.value!=='staff-mini-role')hqOptions.value=await api.hqOptions()}catch(e){error.value=e.message}finally{loading.value=false}}
function edit(row){form.value=row?JSON.parse(JSON.stringify({...row,enabled:!!row.enabled})):{name:business.value==='staff-mini-role'?'门店员工岗位调整':business.value==='staff-reserve-transfer'?'储备人员调动':'正式店长任命',mode:'all',store_ids:[],region_ids:[],fallback_user_ids:[],nodes:[node()],execution:'manual',enabled:true};editing.value=true}
async function save(){if(busy.value)return;busy.value=true;try{await api.templates({...form.value,business:business.value});editing.value=false;await load();ElMessage.success('流程已保存')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function act(row,action){try{let note='';if(['reject','void'].includes(action)){note=(await ElMessageBox.prompt('请填写原因',actions[action],{inputValidator:v=>!!v?.trim()||'必须填写原因'})).value}else await ElMessageBox.confirm(action==='execute'?'按审批内容执行岗位或人事变更；历史记录保留，薪资另行确认。':'确认同意此岗位调整？',actions[action]);await api.decision(row.id,{action,revision:row.revision,note});await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'操作失败')}}
function openAppointment(){appointment.value={employee_id:null,to_store_id:null,position_id:null,effective_date:new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}),reason:''};appointmentOpen.value=true}
async function submitAppointment(){if(busy.value)return;busy.value=true;try{await api.hqStart({...appointment.value,business:business.value});appointmentOpen.value=false;await load();ElMessage.success('已提交总部审批')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
watch(business,()=>{detail.value=null;load()});onMounted(load)
</script>
<style scoped>.workflow{padding:28px;max-width:1500px;margin:auto}header,.toolbar,.node-head{display:flex;justify-content:space-between;align-items:center;gap:20px}header{margin-bottom:24px}h1{font-size:26px;margin:8px 0}small,p{color:#8994a3;font-size:12px;line-height:1.7}.search{width:320px;margin:16px 0}.node{padding:18px;border:1px solid #e6ebf2;background:#fafcff;border-radius:12px;margin:16px 0}.node-head{margin-bottom:12px}.node-controls{display:grid;grid-template-columns:2fr 1fr;gap:12px;margin:12px 0}.el-select{width:100%}.execution{margin-top:24px}.toolbar{margin:14px 0}</style>
